import html
import json
from .core import ROOT, digest, log, now, read_json, write_json

def report():
    from .core import config
    if config().get("session_type") == "qualifying":
        from .timeline import build
        return build()
    catalog=read_json(ROOT/"data/processed/catalog.json")
    editorial=read_json(ROOT/"data/processed/editorial.json")
    videos=read_json(ROOT/"outputs/manifest.json",{}).get("videos",[])
    qa=read_json(ROOT/"outputs/qa.json",{})
    esc=lambda v:html.escape(str(v),quote=True)
    from .feedback import feedback_status
    review=feedback_status(root=ROOT)
    human_review=f'<p class="note">Human review: {esc(review["status"].replace("_"," "))}. This decision applies to the exact current output set and is separate from technical QA.</p>'
    rel=lambda v:"../"+v
    video_cards="".join(f'<article class="film"><video controls playsinline preload="metadata" poster="{esc(rel(v["thumbnail"]))}" src="{esc(rel(v["path"]))}"></video><h3>{esc(v["title"])}</h3><p>{v["duration"]:.1f}s · {v["width"]} × {v["height"]} · H.264 / AAC</p><div class="links"><a download href="{esc(rel(v["path"]))}">MP4</a><a href="{esc(rel(v["captions"]))}">Captions</a><a href="{esc(rel(v["script"]))}">Script</a></div></article>' for v in videos)
    src={s["id"]:s for s in catalog["sources"]};assets={a["id"]:a for a in catalog["assets"]}
    timeline=""
    for e in editorial["timeline"]:
        links="".join(f'<a href="{esc(rel(assets[m["asset_id"]]["proxy"]))}#t={m["in"]},{m["out"]}">{esc(src[m["source_id"]].get("title",m["source_id"]))}</a>' for m in e.get("media_matches",[]))
        data_links="".join(f'<a href="{esc(rel(a["local_path"]))}">Data: {esc(a["description"])}</a>' for a in e.get("data_assets",[]) if a.get("local_path"))
        stamp=e.get("local_time") or e.get("utc_time") or "Time approximate / unverified"
        timeline+=f'<article class="event"><div class="eyebrow">{esc(e["id"])} · {"LAP "+str(e["lap"]) if e.get("lap") else esc(e["phase"].upper())}</div><h3>{esc(e["title"])}</h3><p>{esc(e["summary"])}</p><small>{esc(stamp)} · Confidence: {esc(e["confidence"])}</small><div class="cliplinks">{links or "Original data graphics / footage gap"}{data_links}</div><small>Evidence: {esc(", ".join(e["source_ids"]))}</small></article>'
    ideas="".join(f'<article><div class="eyebrow">PRIORITY {i["rank"]} · EDITORIAL SCORE {i["priority_score"]}/100</div><h3>{esc(i["title"])}</h3><p>{esc(i["angle"])}</p><p class="muted">{len(i["available_asset_ids"])} local video assets · {esc(", ".join(i["event_ids"]))}</p></article>' for i in editorial["ideas"])
    rows=""
    for source in catalog["sources"]:
        a=assets.get(source.get("asset_id"),{})
        local=f'<a href="{esc(rel(a["proxy"]))}">Play proxy</a> · <a href="{esc(rel(a["original"]))}">Original</a> · <a href="{esc(rel(a["contact_sheet"]))}">Frames</a>' if a else esc(source.get("download_status","reference only"))
        title=source.get("title",source["id"])
        tags=source.get("labels",[])
        rows+=f'<tr data-search="{esc((title+" "+" ".join(tags)+" "+str(source.get("drivers",[]))).lower())}"><td><a target="_blank" rel="noopener noreferrer" href="{esc(source.get("url") or "#")}">{esc(title)}</a><small>{esc(source.get("publisher",source.get("platform","")))}</small></td><td>{esc(", ".join(tags))}</td><td>{local}</td><td>{esc(source.get("rights_status","unknown"))}</td></tr>'
    evidence="".join(f'<li><a target="_blank" rel="noopener noreferrer" href="{esc(s.get("url","#"))}">{esc(s.get("title",s["id"]))}</a> <small>{esc(s["id"])}</small></li>' for s in editorial["sources"])
    html_doc='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Singapore Sprint — Race Notes</title><style>
:root{color-scheme:dark;--bg:#09111d;--panel:#12202f;--ink:#edf3f8;--muted:#9fb4c3;--accent:#b7f65d}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.55 -apple-system,BlinkMacSystemFont,Segoe UI,sans-serif}a{color:var(--accent);text-underline-offset:4px}header,main,footer{max-width:1280px;margin:auto;padding:32px}header{padding-top:60px}h1{font-size:clamp(40px,6vw,76px);line-height:1.03;letter-spacing:-3px;max-width:950px;margin:24px 0}h2{font-size:30px;margin-top:58px}h3{line-height:1.25;margin:14px 0}p{max-width:850px}.eyebrow{color:var(--accent);letter-spacing:2px;font-size:12px;font-weight:700}.muted,small{color:var(--muted)}small{display:block}nav{display:flex;gap:22px;flex-wrap:wrap;margin-top:26px}.stats{display:flex;gap:18px;flex-wrap:wrap;margin:36px 0}.stats div{background:var(--panel);padding:18px 28px;border-radius:12px}.stats strong{font-size:30px;display:block}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px}article{background:var(--panel);border:1px solid #263747;border-radius:14px;padding:24px}video{width:100%;max-height:570px;background:black;border-radius:8px}.film{padding:16px}.links{display:flex;gap:20px}.event{border-left:3px solid var(--accent)}.cliplinks{margin:18px 0;display:flex;flex-direction:column;gap:9px}.note{border-left:3px solid #ffaf55;padding:12px 18px;background:#1a2532;color:var(--muted)}input{width:100%;padding:16px;background:var(--panel);border:1px solid #41566a;color:white;border-radius:8px;font-size:16px;margin-bottom:18px}table{width:100%;border-collapse:collapse;font-size:14px}td,th{text-align:left;padding:14px;border-bottom:1px solid #263747;vertical-align:top}td:first-child{width:40%}.scroll{overflow:auto}pre{white-space:pre-wrap;background:var(--panel);padding:18px;border-radius:10px}footer{color:var(--muted);font-size:14px}@media(max-width:700px){header,main,footer{padding:20px}.grid{grid-template-columns:1fr}h1{letter-spacing:-1.5px}td{min-width:180px}}
</style></head><body><header><div class="eyebrow">RACE NOTES / LOCAL PRODUCTION LIBRARY</div><h1>Singapore.<br>Twenty laps. Three turning points.</h1><p class="muted">10 October 2026 · Sprint · Marina Bay. Reviewed footage, traceable evidence, and original narrated edits.</p><nav><a href="#films">Finished edits</a><a href="#timeline">Timeline</a><a href="#ideas">Story queue</a><a href="#library">Source library</a><a href="#evidence">Evidence & workflow</a></nav>'''
    html_doc+=f'<div class="stats"><div><strong>{len(catalog["sources"])}</strong>source records</div><div><strong>{len(catalog["assets"])}</strong>local videos</div><div><strong>{len(editorial["timeline"])}</strong>timeline segments</div><div><strong>{len(editorial["ideas"])}</strong>ranked ideas</div></div></header><main><section id="films"><h2>Finished edits</h2><div class="grid">{video_cards}</div>{human_review}<p class="note">Local editorial review copies. Original narration and data graphics accompany Formula 1 footage. Footage reuse clearance is unverified; no publishing has occurred.</p></section><section id="timeline"><h2>The event timeline</h2><p class="muted">Incident times and announcement times are kept distinct. Clip ranges refer to individual source files.</p><div class="grid">{timeline}</div></section><section id="ideas"><h2>Prioritized story queue</h2><p class="muted">Scores are editorial judgments, not predicted views or measured audience performance. The first idea has been assembled in two formats.</p><div class="grid">{ideas}</div></section><section id="library"><h2>Source library</h2><p class="muted">Search titles, drivers and categories. Indexed references are separate from downloaded videos.</p><input id="search" aria-label="Filter sources" placeholder="Search Russell, collision, interview…"><div class="scroll"><table><thead><tr><th>Source</th><th>Labels</th><th>Local asset</th><th>Rights record</th></tr></thead><tbody>{rows}</tbody></table></div></section><section id="evidence"><h2>Evidence & workflow</h2><div class="links"><a href="../data/processed/editorial.json">Event + ideas JSON</a><a href="../data/processed/catalog.json">Asset catalog</a><a href="edit-plan.json">Edit decisions</a><a href="qa.json">QA report</a><a href="../docs/workflow-design.md">Workflow design</a><a href="../research/jev/REPORT.md">Jev research</a></div><p class="note">AI agents performed research and editorial review. Local code handles downloads, integrity, assembly and validation. Jev integration is contract-tested; no live Jev inference has run because a provider credential is unavailable.</p><h3>Primary evidence</h3><ul>{evidence}</ul><h3>Validation</h3><pre>{esc(json.dumps(qa,indent=2))}</pre></section></main><footer>Built locally · {esc(now())} · No claim of exhaustive internet coverage. Source failures and collection boundaries remain in research/media/coverage.json.</footer><script>document.querySelector("#search").addEventListener("input",e=>{{let q=e.target.value.toLowerCase();document.querySelectorAll("tbody tr").forEach(r=>r.hidden=!r.dataset.search.includes(q))}})</script></body></html>'
    (ROOT/"outputs/index.html").write_text(html_doc)
    stages={"research":"research/event/event_bundle.json","discovery":"research/media/sources.json","collection":"data/processed/data_manifest.json","catalog":"data/processed/catalog.json","analysis":"data/processed/editorial.json","assembly":"outputs/edit-plan.json","render":"outputs/manifest.json","QA":"outputs/qa.json","report":"outputs/index.html"}
    write_json(ROOT/"runs/harness.json",{"at":now(),"execution":"Codex research agents + deterministic local stage runner","stages":[{"stage":s,"artifact":p,"sha256":digest(ROOT/p),"status":"present"} for s,p in stages.items() if (ROOT/p).exists()],"QA_status":qa.get("status"),"retry":"Explicit stage rerun; verified downloads cached; final render replaced atomically"})
    log("report","complete",path="outputs/index.html")
